import channels_graphql_ws
import graphene
from graphql import GraphQLError
from .models import TradingAccount
from .types import OrderFillType

class TradingOrderExecutionSubscription(channels_graphql_ws.Subscription):
    fill = graphene.Field(OrderFillType)

    class Arguments:
        account_number = graphene.String(required=True)

    @classmethod
    def subscribe(cls, root, info, account_number):
        user = info.context.user
        if not user.is_active:
            raise GraphQLError("Trader account is inactive")

        if not TradingAccount.objects.filter(account_number=account_number, authorized_traders=user).exists():
            raise GraphQLError("Unauthorized trading account specified")

        return [f"account_fills_{account_number}"]

    @classmethod
    def publish(cls, payload, info, account_number):
        return cls(fill=payload["fill_data"])
